const upsertBankFeedConnection = `-- name: UpsertBankFeedConnection :one
INSERT INTO invoices.bank_feed_connections (
    id, provider, secret_ciphertext, key_last4, status, rejected_at, connected_by_user_id, connected_at, updated_at
) VALUES (
    1, $1, $2, $3, 'ok', NULL, $4, $5::timestamptz, $5::timestamptz
)
ON CONFLICT (id) DO UPDATE SET
    provider = EXCLUDED.provider,
    secret_ciphertext = EXCLUDED.secret_ciphertext,
    key_last4 = EXCLUDED.key_last4,
    status = 'ok',
    rejected_at = NULL,
    connected_by_user_id = EXCLUDED.connected_by_user_id,
    connected_at = EXCLUDED.connected_at,
    updated_at = EXCLUDED.updated_at
RETURNING id, provider, secret_ciphertext, key_last4, status, rejected_at, connected_by_user_id, connected_at, updated_at
`

type UpsertBankFeedConnectionParams struct {
	Provider          string
	SecretCiphertext  string
	KeyLast4          string
	ConnectedByUserID uuid.UUID
	Now               time.Time
}

// UpsertBankFeedConnection stores a key the bank accepted (F3): the first, or
// one over the stored row, which the statement locks — two PUTs at once store
// one row, the later one's. A new key is ok until the bank refuses it, and
// connected_by and connected_at are its own. updated_at is the key's version
// (MarkBankFeedUnauthorized).
func (q *Queries) UpsertBankFeedConnection(ctx context.Context, arg UpsertBankFeedConnectionParams) (InvoicesBankFeedConnection, error) {
	row := q.db.QueryRow(ctx, upsertBankFeedConnection,
		arg.Provider,
		arg.SecretCiphertext,
		arg.KeyLast4,
		arg.ConnectedByUserID,
		arg.Now,
	)
	var i InvoicesBankFeedConnection
	err := row.Scan(
		&i.ID,
		&i.Provider,
		&i.SecretCiphertext,
		&i.KeyLast4,
		&i.Status,
		&i.RejectedAt,
		&i.ConnectedByUserID,
		&i.ConnectedAt,
		&i.UpdatedAt,
	)
	return i, err
}
